INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('000094d7-4067-4699-b6a2-150afb4f0cf8', 'Forward Lunge Punch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Works well as both a primary exercise or accessory movement.', '74431201', '74431201-Forward-Lunge-Punch-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Forward Lunge Punch', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0005631e-dc90-4ec8-b2f4-9d7841e63acb', 'Jackknife (Donkey) Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness. Keep your core engaged throughout the exercise.', '69351201', '69351201-Jackknife-(Donkey)-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'v_up', 'Jackknife  Squat', 'Jackknife Squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('0005effc-a444-4555-95b9-b972f60318a5', 'Incline Squeeze Press (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Upper Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Dumbbell Incline Squeeze Press is an arm pressing exercise targeting your chest. You''ll also feel your triceps working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '80001201', '80001201-Dumbbell-Incline-Squeeze-Press-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Squeeze Press. 2. Execute the pressing motion for Dumbbell Incline Squeeze Press, extending through the target muscles. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squeeze_press', 'Incline Squeeze Press', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('0006bfce-22fe-4cc1-94e4-557133975322', 'Boat Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This stretching exercise engages your abs for improved core stability and strength. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Progress gradually by increasing resistance over time.', '42791201', '42791201-Boat-Stretch-(male)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up in the starting position for Boat Stretch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Boat Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('000ccfd7-3adb-46ee-b19a-5b0c2fd6deac', 'Sumo Hip Twist Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'The Sumo Hip Twist Stretch provides a deep stretch for your hips, ideal for recovery and mobility work. You''ll also feel your glutes working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '63211201', '63211201-Sumo-Hip-Twist-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Rotate your torso through the movement pattern for Sumo Hip Twist Stretch. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Sumo Hip Twist Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Sumo Hip Twist Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('000fd58e-f7c9-41df-830f-fc35782239b5', 'Bicep Curl - Close Grip (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '100691201', '100691201-Band-Close-Grip-Biceps-Curl-(female)_Upeer-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Close Grip Biceps Curl. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting. Keep tension on the target muscles throughout.', 'Curl', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Underhand', 'Standard', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'bicep_curl', 'Bicep Curl - Close Grip', 'Bicep Curl - Close Grip', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('002f7038-ad4b-4d95-8c61-863022e28068', 'Seated Side Leg Lift (Chair) - Alternating', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Alternate Side Leg Lift On A Chair is a lower body movement exercise that targets your hip abductors. Being seated provides stability, allowing you to focus on the working muscles. Strong legs are the foundation for athletic performance and functional fitness.', '76321201', '76321201-Sitting-Alternate-Side-Leg-Lift-on-a-Chair-(female.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Alternate between sides/arms/legs with each repetition. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Side Leg Lift On A Chair - Alternating', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('00465e03-9f68-4f38-8136-aced2b09c38f', 'Lateral Pulldown - Rope Attachment (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '1771201', '01771201-Cable-Lateral-Pulldown-(with-rope-attachment)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lateral Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lateral Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('00480c96-1f5b-4b79-bc3d-0276efc8a4a4', 'Lying Obliques Crunch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Lying Obliques Crunch is a core crunching exercise that primarily targets your abs. Secondary activation of your abs provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '65911201', '65911201-Lying-Obliques-Crunch-(VERSION-2)-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Lie down in the appropriate position for Lying Obliques Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Obliques Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('004c25db-b22c-419e-91d3-a2291e4a22e1', 'Full Clean (Barbell)', 'Full Body', 'Barbell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'Develop functional strength with the Barbell Full Clean, a comprehensive movement exercise. You''ll also feel your quads, glutes, traps working to support the movement. Barbells enable bilateral loading for building raw strength. Compound movements like this develop coordination, power, and overall fitness.', '52871201', '52871201-Barbell-Full-Clean_Weightlifting-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Grip a barbell with hands at the appropriate width for Barbell Full Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Full Clean', 'power_clean, deadlift, front_squat', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('0053b84e-8897-4f3d-95ef-681d7066baa8', 'Standing Top Backhand Tap And Backhand Prayer Push', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this pushing exercise that develops speed, power, and coordination. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '95401201', '95401201-Standing-Top-Backhand-Tap-And-Backhand-Prayer-Push.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Top Backhand Tap And Backhand Prayer Push. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'boxing', 'Standing Top Backhand Tap And Backhand Prayer Push', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0053edd8-7cb9-4dc5-9f8f-bb2f9fa9970f', 'Step Up On Box (Plyo Box)', 'Legs', 'Plyo Box', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this stepping movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '94901201', '94901201-Step-Up-on-Box_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'step_up', 'Step Up On Box', 'lunge, split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0063756f-f734-42c6-851c-9b31e167ac6a', 'Lying Frog Crunch Feet Together', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '62841201', '62841201-Lying-Frog-Crunch-Feet-Together-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Frog Crunch Feet Together. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Frog Crunch Feet Together', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('006b23b7-dce2-4608-b99f-e083ad9c6411', 'Two Front Toe Touching', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Two Front Toe Touching is a core movement exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '32491201', '32491201-Two-Front-Toe-Touching-(female).mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up in the starting position for Two Front Toe Touching. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'toe_touch', 'Two Front Toe Touching', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('006ddc82-05c7-456b-9f99-d562e5db2558', 'Elbow Plank 3 Point Hops', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'A challenging plyometric exercise, the Elbow Plank 3 Point Hops builds reactive power and improves conditioning. You''ll also feel your shoulders, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '78601201', '78601201-Elbow-Plank-3-Point-Hops-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Elbow Plank 3 Point Hops', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('0094d406-0de4-4c76-9dec-fe56b7b99047', 'Reverse Lunge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'The Bodyweight Reverse Lunge is a lunging exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '63881201', '63881201-Bodyweight-Reverse-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. An effective movement for your legs routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('00968b97-0806-4b10-a69d-5255a1c2a793', 'Seated Hip Mobilization (Stability Ball)', 'Legs', 'Stability Ball', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Hip Mobilization On Exercise Ball is a flexibility exercise that targets your glutes, helping to release tension and improve range of motion. The seated position helps isolate the target muscles by removing momentum. Using a ball requires constant core engagement to maintain balance. Include this in your routine for better mobility and reduced muscle tension.', '98281201', '98281201-Sitting-Hip-Mobilization-on-Exercise-Ball-(male)_S.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Position the stability ball as needed for Seated Hip Mobilization On Exercise Ball. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Hip Mobilization On Exercise Ball. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'mobility', 'Seated Hip Mobilization On Exercise Ball', 'hip_thrust, lunge, squat', FALSE, 'stability_ball', TRUE, 1, 30, 2, 70, 88, 95, 65),
('009db59e-ef6c-4326-bf3f-3428da1ee608', 'Cross Body Hammer Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This dynamic curling movement gets your heart rate up while developing explosive strength. You''ll also feel your shoulders, core working to support the movement. Cables provide constant tension throughout the full range of motion. Plyometric training builds explosive power that transfers to sports and daily activities.', '83401201', '83401201-Cable-Cross-Body-Hammer-Curl-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the cable machine to the correct height and attachment for Cable Cross Body Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'hammer_curl', 'Cross Body Hammer Curl', 'bicep_curl, preacher_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('009efb29-728d-410a-bcd8-1c1a3ceb4183', 'Standing Scapular External Rotation (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger back with this rotation movement targeting your rotator cuff. The standing position engages your core for stability. Dumbbells allow each arm to work independently, helping correct imbalances. A strong back improves posture, prevents injury, and balances pressing movements. Excellent for pre-exhausting the target muscle before compound lifts.', '72351201', '72351201-Dumbbell-Standing-Scapular-External-Rotation-(back-POV)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Scapular External Rotation. 2. Begin in a standing position with good posture. 3. Rotate your torso through the movement pattern for Dumbbell Standing Scapular External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 46, 7, 8, TRUE, TRUE, 'external_rotation', 'Standing Scapular External Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('00afbf39-4e1d-4b82-adbc-f2be0640d96c', 'Seated Overhead Triceps Extension', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Being seated provides stability, allowing you to focus on the working muscles. Dedicated arm training builds both strength and muscular definition.', '84701201', '84701201-Seated-Overhead-Triceps-Extension-(female)_Upper-A.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated Overhead Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('00d30699-1ce9-41cc-9286-0e07184e690d', 'V Up Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The V Up Hold is a core movement exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '54921201', '54921201-V-Up-Hold-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Hold the position for the prescribed time, maintaining tension. 2. Set up in the starting position for V Up Hold. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'v_up', 'V Up Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('00d762df-6515-4d9c-977e-d604f0637d4d', 'Lying Front Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This raising exercise works your front delts for improved shoulder strength and aesthetics. Performing this lying down removes momentum for stricter form. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '91911201', '91911201-Dumbbell-Lying-Front-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Front Raise. 2. Lie down in the appropriate position for Dumbbell Lying Front Raise. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Lying Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('01089d66-3dc7-425a-a73e-d85fc4ed5b37', 'Bottoms Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Bottoms Up, focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '24361201', '24361201-Bottoms-Up-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Set up in the starting position for Bottoms Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'bottoms_up', 'Bottoms Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('01092151-73d6-4117-9db0-14987d8fa88f', 'Kneeling Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Pulse is a lower body movement exercise that targets your core. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '46561201', '46561201-Kneeling-Pulse_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pulse', 'Kneeling Pulse', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('011294f0-7deb-4072-bd59-c34ff1e49a72', 'Reverse Lunge Front Kick', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '73871201', '73871201-Reverse-Lunge-Front-Kick-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge Front Kick', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('01199d16-498e-4a29-800d-7fdf82121631', 'Push Up (Stability Ball)', 'Chest', 'Stability Ball', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Push Up (stability Ball), an effective pushing movement for upper body strength. Your triceps, front delts work as secondary movers, adding to the training stimulus. Using a ball requires constant core engagement to maintain balance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '26791201', '26791201-Push-Up-(on-stability-ball)-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Position the stability ball as needed for Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', TRUE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('011c8e91-7d3a-400b-95ad-f0b6e3b390f6', '45 Degrees Arms Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. Secondary activation of your shoulders, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Can be modified for beginners or progressed for advanced athletes.', '103681201', '103681201-45-degrees-Arms-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', '45 Degrees Arms Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('011e05b1-07ce-4f3a-b2a3-5ed6b444f4fe', 'Rocking Frog Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension. Can be modified for beginners or progressed for advanced athletes.', '61671201', '61671201-Rocking-Frog-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Rocking Frog Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Rocking Frog Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('01215a7d-8e38-4ecb-a168-01bb03915b23', 'Shoulder Grip Upright Row (Barbell)', 'Shoulders', 'Barbell', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. Your traps work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Strong shoulders improve overhead strength and support nearly all upper body movements.', '23661201', '23661201-Barbell-Shoulder-Grip-Upright-Row-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Shoulder Grip Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'upright_row', 'Shoulder Grip Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('0155e04b-587e-429b-ad0d-ff3967d13390', 'Bent Over Single Arm Triceps Kickback (Resistance Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Develop your posterior chain with this kicking movement that emphasizes the glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Bending over allows gravity to provide resistance in a different plane. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '91371201', '91371201-Resistance-Band-Bent-Over-Single-Arm-Triceps-Kickb.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Bent Over Single Arm Triceps Kickback. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 40, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Bent Over Single Arm Triceps Kickback', 'tricep_pushdown, tricep_extension', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('015b723b-db6b-458a-88c0-12f2d98c1af6', 'Lateral Swing And Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lateral Swing And Knee Raise is an explosive exercise that combines cardiovascular training with dynamic raising movements. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '66751201', '66751201-Lateral-Swing-and-Knee-Raise(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Lateral Swing And Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('01713d44-50a0-4d09-b693-549769a7a7c3', 'Knee Thrust', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity thrusting exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Quality repetitions are more important than quantity.', '45041201', '45041201-Bodyweight-Knee-Thrust_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Knee Thrust', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('01716994-c0d0-4a34-8c86-c74bf6885ff5', 'Standing Wide Stance Air Bike', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '79441201', '79441201-Standing-Wide-Stance-Air-Bike-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Wide Stance Air Bike. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 37, 9, 8, FALSE, TRUE, 'cycling', 'Standing Wide Stance Air Bike', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('0192c5ab-26dc-40b3-b102-56f1a286c6ff', 'Straight Arm Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger chest with this pulling movement that develops pressing power. The lats, triceps assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. A well-developed chest contributes to upper body strength and aesthetics.', '71131201', '71131201-Dumbbell-Straight-Arm-Pullover-(VERSION-2)-(female.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Straight Arm Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Straight Arm Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('0198c34b-7172-4632-bc97-a7fc1b9f7f2e', 'Hip Thrust (Machine)', 'Legs', 'Machine', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '21461201', '21461201-Lever-Hip-Thrust_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'hip_thrust', 'Lever Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('01999010-a7d7-4ccf-bfa0-6b6e38af4086', 'Paused Goblet Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Aim for full range of motion on every rep.', '68841201', '68841201-Bodyweight-Paused-Goblet-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Pause for 1-3 seconds at the bottom or peak of the movement before continuing. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'goblet_squat', 'Paused Goblet Squat', 'squat, front_squat, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('019c318b-3eff-4833-ba03-8a7ba1fe71d2', 'Rear Delt Row (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This rowing exercise works your rear delts for improved shoulder strength and aesthetics. Secondary activation of your upper back provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '3771201', '03771201-Dumbbell-Rear-Delt-Row_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Delt Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'rear_delt', 'Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('01a010ca-5acc-4e23-a051-28972d6387eb', 'Kneeling Arnold Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Kneeling Arnold Press, an effective shoulder pressing exercise. Secondary activation of your triceps provides additional muscle engagement. The kneeling position adds a core stability challenge. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '47451201', '47451201-Dumbbell-Kneeling-Arnold-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Kneeling Arnold Press. 2. Kneel on the floor (use a pad for comfort if needed). 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'Kneeling Arnold Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('01a7a1c4-e76f-4b3f-b724-407f8dcbe19c', 'Side To Side Biceps Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This dynamic curling movement gets your heart rate up while developing explosive strength. Your forearms work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '66431201', '66431201-Side-to-Side-Bicep-Curl-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Side To Side Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('01a8b3bf-040e-4e6a-8021-95085aba8dc6', 'High Knee Twist', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. You''ll also feel your hip flexors working to support the movement. Regular cardio training builds the aerobic base for better overall fitness. Maintain proper breathing - exhale during the effort phase.', '4801201', '04801201-High-Knee-Twist-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Rotate your torso through the movement pattern for High Knee Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Twist', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('01ac9802-897c-467a-93f1-7e6046870429', 'Reverse Warrior Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hip Flexors","Core"}'::text[], 'The Reverse Warrior Pose is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Secondary activation of your hips, shoulders, quads provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '59131201', '59131201-Reverse-Warrior-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Move into the stretch position for Reverse Warrior Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Reverse Warrior Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('01acf60a-de12-4275-94cb-aec24feed963', 'Head Full Rotation Fpov', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{}'::text[], 'Strengthen your neck with this rotation exercise for improved stability. A versatile bodyweight movement perfect for home or gym training. Include this exercise in your routine for balanced strength development.', '59481201', '59481201-Head-Full-Rotation-fPOV-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Rotate your torso through the movement pattern for Head Full Rotation Fpov. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'neck_stretch', 'Head Full Rotation Fpov', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('01b04789-2a67-474a-b5dc-2c5edf81b4a4', 'Vibrate Plate Plank (Vibration Plate)', 'Core', 'Vibration Plate', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Designed to lengthen your lats, the Vibrate Plate Plank helps improve mobility and prevent stiffness. Your shoulders work as secondary movers, adding to the training stimulus. Flexibility work like this enhances performance and prevents stiffness.', '25261201', '25261201-Vibrate-Plate-Plank-(female)_Stretching.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'plank', 'Vibrate Plate Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('01bee80e-324b-4633-92b5-76224ffccabf', 'Single Split Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Single Split Stretch provides a deep stretch for your full body, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84451201', '84451201-Single-Split-Stretch-(beginner)-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Move into the stretch position for Single Split Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Single Split Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('01e4b23a-0fb9-4f6f-9be8-0d0bce1773c1', 'Opposite Arm & Leg Raise (Against Wall)', 'Core', 'Wall', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Leg training boosts metabolism and builds functional, real-world strength.', '86381201', '86381201-Opposite-Arm-and-Leg-Raise-against-Wall-(female)_H.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Position yourself at the appropriate distance from a wall. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'leg_raise', 'Opposite Arm And Leg Raise Against Wall', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('01e90a6b-a369-456f-888d-cd26af8fdcdf', 'Seated Triceps Stretch (Chair)', 'Arms', 'Chair', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Designed to lengthen your triceps, the Seated Triceps Stretch On A Chair helps improve mobility and prevent stiffness. Your shoulders work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '91691201', '91691201-Sitting-Triceps-Stretch-on-a-Chair-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Triceps Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Triceps Stretch On A Chair', 'bicep_curl, dip', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('01e98633-98af-456b-8d46-833e43a561d7', 'Rollout (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The lats, shoulders assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. A strong core improves posture, protects your spine, and enhances all other lifts.', '10911201', '10911201-Suspender-Rollout-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Rollout. 2. Set up in the starting position for Suspender Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'ab_rollout', 'Suspender Rollout', 'plank, crunch, dead_bug', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('01ec02d1-3466-489d-9fe7-7f03a1c9a33a', 'Single Arm Twisting Seated Delt Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise works your obliques for improved shoulder strength and aesthetics. You''ll also feel your abs working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The band creates increasing tension as it stretches, challenging the lockout. Shoulder development enhances both performance and upper body aesthetics.', '99201201', '99201201-Band-One-Arm-Twisting-Seated-Delt-Row-(female)_Sho.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band One Arm Twisting Seated Delt Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 64, 7, 8, TRUE, TRUE, 'russian_twist', 'Single Arm Twisting Seated Delt Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('01fb980f-eb18-478a-9114-84036ee7a40f', 'Reverse Lunge From Deficit (Dumbbell)', 'Legs', 'Dumbbells, Step Platform', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '73261201', '73261201-Dumbbell-Reverse-Lunge-from-Deficit-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Reverse Lunge From Deficit. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge From Deficit', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('02060d09-4a1a-454a-8cb2-1e5f52fd81ab', 'Side Reach Diagonal Reach', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Side Reach Diagonal Reach builds reactive power and improves conditioning. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '68561201', '68561201-Side-Reach-Diagonal-Reach-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Set up in the starting position for Side Reach Diagonal Reach. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'lat_stretch', 'Side Reach Diagonal Reach', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('020c7e4e-e198-4191-bfb4-48b2c1a3fb99', 'Front Plank With Arm Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '28941201', '28941201-Front-Plank-with-Arm-Lift-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. An effective movement for your core routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Front Plank With Arm Lift', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('021810e0-6621-48c0-a9b6-011d325f38e0', 'Between Legs Throw Side Kick', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Elevate your training with this rowing exercise that develops speed, power, and coordination. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '69111201', '69111201-Between-Legs-Throw-Side-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. Perfect for targeting your upper back.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'leg_exercise', 'Between Legs Throw Side Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('021de3ac-3121-4eaf-841f-8fc296683f15', 'Leg Extension Glute Bridge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hamstrings"}'::text[], 'This extension exercise isolates your glutes for improved hip strength and power. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '66841201', '66841201-Leg-Extension-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_extension', 'Leg Extension Glute Bridge', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('02281e6e-cc0e-43aa-869f-72f0ce31cffd', 'Interlock Fist Circle Draw', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements. Progress gradually by increasing resistance over time.', '81391201', '81391201-Interlock-Fist-Circle-Draw-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Set up in the starting position for Interlock Fist Circle Draw. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Interlock Fist Circle Draw', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0234b45d-3172-4e15-8b60-4674cc181dd9', 'Shuffle Hops', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'The Shuffle Hops is a lower body movement exercise that targets your full body. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '66741201', '66741201-Shuffle Hops-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up in the starting position for Shuffle Hops. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'shuffle', 'Shuffle Hops', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('023d9386-d66b-44e9-9aa7-20e5631c1f84', 'Chest Press (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics. Excellent for pre-exhausting the target muscle before compound lifts.', '24571201', '24571201-Lever-Chest-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('02447852-53ea-4090-8b3c-caf18958a70d', 'Silent Burpee', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'A challenging plyometric exercise, the Silent Burpee builds reactive power and improves conditioning. Your chest, quads work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '50391201', '50391201-Silent-Burpee-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Squat down and place hands on the floor, jump feet back to plank. 2. Jump feet back toward hands, then explosively jump up with arms overhead. 3. Land softly and immediately begin the next rep. 4. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'burpee', 'Silent Burpee', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('027ee6bb-41ed-4299-a932-a81c69f4ec83', 'Balance Pad Single Leg Balance (Balance Pad)', 'Legs', 'Balance Pad', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your full body, the Balance Pad Single Leg Balance helps improve mobility and prevent stiffness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '107341201', '107341201-Balance-Pad-Single-Leg-Balance-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Move into the stretch position for Balance Pad Single Leg Balance. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. 5. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'balance', 'Balance Pad Single Leg Balance', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('02915da8-9746-47d7-8895-0950e61cbe14', 'Easy Pose (hands On Belly And Chest)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'The Easy Pose (hands On Belly And Chest) is a flexibility exercise that targets your chest, helping to release tension and improve range of motion. Your shoulders work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '81671201', '81671201-Easy-Pose-(hands-on-belly-and-chest)-(female)_Stre.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Easy Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'chest_exercise', 'Easy Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('029dca1c-859e-43c0-a41e-caf590837c75', 'Windmill', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts. Start with lighter weight to master the movement pattern.', '39491201', '39491201-Bodyweight-Windmill-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Set up in the starting position for Bodyweight Windmill. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Windmill', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('02a43095-1ae4-47ed-914b-a2261049814a', 'Skipping', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'The Bodyweight Skipping is an explosive exercise that combines cardiovascular training with dynamic movement movements. Your calves work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '61011201', '61011201-Bodyweight-Skipping-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Set up in the starting position for Bodyweight Skipping. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'skip', 'Skipping', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('02adb8c2-bdfe-4e98-a8cd-9c50e04da99b', 'Palms To Head Chest Fly', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Palms To Head Chest Fly, an effective flying movement for upper body strength. You''ll also feel your front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '80551201', '80551201-Palms-to-Head-Chest-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Palms To Head Chest Fly', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('02ae2237-26d7-4ab3-b036-15cb7cbb8c9b', 'Chair Squat Calf Rock (Chair)', 'Legs', 'Chair', '{"Calves"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement focuses on your gastrocnemius and soleus. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '89481201', '89481201-Chair-Squat-Calf-Rock-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Keep the movement smooth and controlled.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'squat', 'Chair Squat Calf Rock', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('02b244dd-c029-4b7e-b457-4404cd9a8693', 'Narrow To Normal Squat', 'Legs', 'Bodyweight', '{"Quads","Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger quads with this rowing movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '66871201', '66871201-Narrow-to-Normal-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Narrow To Normal Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('02c7e546-78ac-4f16-b1fe-1c136fa0ab5d', 'Bench Press (Plate)', 'Chest', 'Weight Plate, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Weighted Plate Bench Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '98081201', '98081201-Weighted-Plate-Bench-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'bench_press', 'Weighted Plate Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('02d5090e-229b-44b6-8df5-35994c110cd1', 'Leg Calf Raise - Standing (Smith Machine)', 'Legs', 'Smith Machine', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The standing position engages your core for stability. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '7731201', '07731201-Smith-Standing-Leg-Calf-Raise_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Standing Leg Calf Raise. 2. Begin in a standing position with good posture. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Smith Standing Leg Calf Raise', 'Standing Leg Calf Raise', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('02d87635-d6a8-4c90-bb33-50b7af17d1d8', 'Side Step Shoulder Circle', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Side Step Shoulder Circle builds reactive power and improves conditioning. Plyometric training builds explosive power that transfers to sports and daily activities.', '92551201', '92551201-Side-Step-Shoulder-Circle-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Shoulder Circle. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Side Step Shoulder Circle', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('02e3fc37-9ecc-42d3-9f51-511d184218b6', 'Y Press (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The band creates increasing tension as it stretches, challenging the lockout. Shoulder development enhances both performance and upper body aesthetics.', '73231201', '73231201-Resistance-Band-Y-Press-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Secure the resistance band appropriately for Resistance Band Y Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'shoulder_press', 'Y Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('02e94c2b-bd99-4f06-b88b-0cb03dda7492', 'Lying Woodchop (Kettlebell)', 'Core', 'Kettlebell', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Kettlebell Lying Woodchop targets your obliques through a movement motion, building rotational core strength. The lying position provides back support and helps isolate the target muscles. The kettlebell''s offset center of mass increases the stability challenge. Building core stability helps with everything from heavy deadlifts to daily activities.', '83381201', '83381201-Kettlebell-Lying-Woodchop_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select an appropriately weighted kettlebell for Kettlebell Lying Woodchop. 2. Lie down in the appropriate position for Kettlebell Lying Woodchop. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 58, 9, 8, TRUE, TRUE, 'woodchop', 'Lying Woodchop', 'russian_twist, pallof_press, cable_crunch', FALSE, 'kettlebell', FALSE, 3, 60, 4, 75, 88, 88, 78),
('02f2d0ef-5727-4d6b-8ca1-d9bfc5c19a8c', 'Ballerina Foot Tap Adduction', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your adductors. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '56041201', '56041201-Ballerina-Foot-Tap-Adduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Ballerina Foot Tap Adduction. 2. Execute the movement with proper form, focusing on your adductors. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'yoga', 'Ballerina Foot Tap Adduction', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('02f76ed7-9a7a-4e8e-b682-bc77031ac7b3', 'Reverse Crunch (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Reverse Crunch is a core crunching exercise that primarily targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. A strong core improves posture, protects your spine, and enhances all other lifts.', '64181201', '64181201-Resistance-Band-Reverse-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Secure the resistance band appropriately for Resistance Band Reverse Crunch. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('02f7a43a-5245-4ce7-accf-91b57b74ae18', 'Decline Bench Press - Close Grip (Smith Machine)', 'Chest', 'Smith Machine, Decline Bench', '{Pectorals}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Smith Machine Decline Close Grip Bench Press targets your triceps through a pressing motion. You''ll also feel your chest working to support the movement. Declining shifts the emphasis to hit the muscles from a different angle. The machine guides your movement path for safer, more controlled repetitions. Dedicated arm training builds both strength and muscular definition.', '16251201', '16251201-Smith-Machine-Decline-Close-Grip-Bench-Press_Upper.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Smith Machine Decline Close Grip Bench Press. 2. Set the bench to a decline angle and secure your feet. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Lower the weight toward your chest with control. 5. Press the weight up until your arms are extended (don''t lock elbows). 6. Repeat for the prescribed number of repetitions.', 'Decline Press', 'Push', 'Compound', 'Bilateral', NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'close_grip_bench', 'Smith Decline Bench Press - Close Grip', 'Decline Bench Press - Close Grip', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('030185eb-16a1-498c-877e-67d1cccca7d8', 'Anti Gravity Press (EZ Bar)', 'Shoulders', 'EZ Bar', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Barbells enable bilateral loading for building raw strength. Shoulder development enhances both performance and upper body aesthetics.', '36031201', '36031201-EZ-Barbell-Anti-Gravity-Press-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Anti Gravity Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'EZ Anti Gravity Press', 'EZ Anti Gravity Press', FALSE, 'ez_bar', FALSE, 3, 90, 4, 95, 80, 65, 95),
('0302a712-0d03-4512-ba32-08c61744d6bd', 'Curtsey Cross Punch', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'The Curtsey Cross Punch is an explosive exercise that combines cardiovascular training with dynamic movement movements. The shoulders, core assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '82871201', '82871201-Curtsey-Cross-Punch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up in the starting position for Curtsey Cross Punch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Curtsey Cross Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0315d1ee-5a2b-4642-85b1-7c3a2168337a', 'Standing Back Squeeze', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger back with this movement movement targeting your full body. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '49411201', '49411201-Standing-Back-Squeeze-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Back Squeeze. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Back Squeeze', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('031b0c00-f263-4ad9-a88e-22cb7fa2ce85', 'Seated Extended Leg Raise (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. You''ll also feel your hip flexors working to support the movement. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '84281201', '84281201-Seated-Extended-Leg-Raise-on-a-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Extended Leg Raise On A Chair', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('031bbd65-19f3-4bc7-887a-418a52bf3329', 'Low Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Low Fly is a flying exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '22521201', '22521201-Cable-Low-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Low Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('032175cb-3a9d-458a-ac76-6652b48c2745', 'Recumbent Hip External Rotator And Hip Extensor St', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this movement movement that emphasizes the glutes. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '61651201', '61651201-Recumbent-Hip-External-Rotator-and-Hip-Extensor-St.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up in the starting position for Recumbent Hip External Rotator And Hip Extensor St. 2. Execute the movement with proper form, focusing on your glutes. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Recumbent Hip External Rotator And Hip Extensor St', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('03333ae8-72ce-4be9-b561-1bc30e9a0d52', 'Shoulder Rotation Twist Split Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads","Glutes","Hamstrings"}'::text[], '{"Shoulders"}'::text[], 'This stretch specifically works on your shoulders, promoting flexibility and reducing muscle tightness. The upper back assist throughout the movement, making this a well-rounded exercise. Flexibility work like this enhances performance and prevents stiffness.', '56401201', '56401201-Shoulder-Rotation-Twist-Split-Lunge-Stretch-(male).mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Shoulder Rotation Twist Split Lunge Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Shoulder Rotation Twist Split Lunge Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('034943be-8546-49c2-a258-1247916aebe7', 'Seated Wrist Rotation', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'The Seated Wrist Rotation strengthens your forearms and grip through a rotation motion. Being seated provides stability, allowing you to focus on the working muscles. Dedicated arm training builds both strength and muscular definition.', '82431201', '82431201-Seated-Wrist-Rotation-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Wrist Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'wrist_stretch', 'Seated Wrist Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('0350a46b-6dff-4e67-967c-c29f6ec01326', 'Hollow Rock (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Dumbbell Hollow Rock, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Building core stability helps with everything from heavy deadlifts to daily activities.', '93371201', '93371201-Dumbbell-Hollow-Rock-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hollow Rock. 2. Set up in the starting position for Dumbbell Hollow Rock. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'hollow_hold', 'Hollow Rock', 'squat, bench_press, deadlift', TRUE, 'dumbbell', TRUE, 3, 90, 4, 92, 90, 92, 90),
('0358b9fc-0271-4c80-ab55-55fc6edbda50', 'Seated Ballerina', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. The seated position helps isolate the target muscles by removing momentum. Strong shoulders improve overhead strength and support nearly all upper body movements. Keep your core engaged throughout the exercise.', '51341201', '51341201-Seated-Ballerina-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Ballerina. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'yoga', 'Seated Ballerina', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('035e3807-f834-4547-a780-053eff490d2e', 'Chin Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this movement movement. You''ll also feel your biceps working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '23791201', '23791201-Chin-Up-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Pull yourself up, focusing on bicep and lat engagement. 2. Raise until chin is over the bar, lower with full control. 3. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('036bdc3a-edd4-4782-91ce-f5901fc6fa1a', 'Linear (Hack Squat Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Lower body strength improves everything from walking to heavy compound lifts.', '65231201', '65231201-Lever-Linear-Hack-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Linear Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'hack_squat', 'Lever Linear Hack Squat', 'leg_press, squat, leg_extension', TRUE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('036c8bd3-7092-47d1-9d05-c73dd00f55cf', 'Twist - Up Down (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. Cable resistance creates smooth, continuous muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '8621201', '08621201-Cable-twist-(up-down)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Adjust the cable machine to the correct height and attachment for Cable Twist. 2. Rotate your torso through the movement pattern for Cable Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('037257f8-2865-40d3-874c-363431208fdb', 'Incline Chest Press (Band)', 'Chest', 'Resistance Band, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Band Incline Chest Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. The band creates increasing tension as it stretches, challenging the lockout. A well-developed chest contributes to upper body strength and aesthetics.', '57391201', '57391201-Band-Incline-Chest-Press_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Secure the resistance band appropriately for Band Incline Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Chest Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('0372fbbd-92e7-4e65-9a39-4e0bd1cf16e2', 'Box Drop Jump (Plyo Box)', 'Legs', 'Plyo Box', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Secondary activation of your quads, calves provides additional muscle engagement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '96061201', '96061201-Box-Drop-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Box Drop Jump. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'box_jump', 'Box Drop Jump', 'squat, burpee, broad_jump', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('037b7dac-940c-4ee8-9e4e-9ec5b72b6128', 'Deep Squat Turn', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{}'::text[], 'This stretch specifically works on your quads, promoting flexibility and reducing muscle tightness. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '85721201', '85721201-Deep-Squat-Turn-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Maintain consistent tempo throughout the set. A solid choice for stretching day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Deep Squat Turn', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('037f8ccc-2f36-4141-a790-2087e8f6323e', 'Reverse Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Reverse Plank, focusing on your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '54541201', '54541201-Reverse-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Reverse Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('03931ab5-e5b3-42a6-97d8-65faf5527e8c', 'Rear Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '52921201', '52921201-Bodyweight-Rear-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Rear Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('039ed423-35e0-42a4-a5fc-ff5975e3e6ef', 'Side Press (Dumbbell) - Alternating', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '2861201', '02861201-Dumbbell-Alternate-Side-Press_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Alternate Side Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Press - Alternating', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('03a7eb60-3061-415a-92ff-1b49c469e3a8', 'Grasshopper Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger back with this pushing movement targeting your chest. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '4681201', '04681201-Grasshopper-Push-up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity. Ideal for chest strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Grasshopper Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('03ba5677-ce35-4bf6-94ba-3535f832cfb9', 'Floor T Raise', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Floor T Raise is a lower body raising exercise that targets your rear delts. Your upper back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '32051201', '32051201-Floor-T-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Position yourself on the floor for Floor T Raise. 2. Raise the weight in the prescribed direction for Floor T Raise. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'lateral_raise', 'Floor T Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('03be9eff-8fcf-4e27-8a4d-de7b82f7fc35', 'Slopes Towards Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this stretching stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Progress gradually by increasing resistance over time.', '7451201', '07451201-Slopes-Towards-Stretch-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Move into the stretch position for Slopes Towards Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Slopes Towards Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('03c66f3a-0260-4fc9-b6cd-4c14350aac34', 'Push Knees Out', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. This variation is excellent for building mind-muscle connection.', '85691201', '85691201-Push-Knees-Out-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Move into the stretch position for Push Knees Out. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_stretch', 'Push Knees Out', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('03c825e8-5a1d-492c-8b83-dc9403535fd4', 'Kneeling Torso Rotation Chest And Shoulder Stretch', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Kneeling Torso Rotation Chest And Shoulder Stretch provides a deep stretch for your shoulders, ideal for recovery and mobility work. The upper back assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. Flexibility work like this enhances performance and prevents stiffness.', '87341201', '87341201-Kneeling-Torso-Rotation-Chest-and-Shoulder-Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Torso Rotation Chest And Shoulder Stretch. 3. Control the rotation in both directions—avoid using momentum. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Kneeling Torso Rotation Chest And Shoulder Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('03c85816-0c46-4fcb-9c3a-5f10fa6f0a79', 'Bear Crawl', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities. Quality repetitions are more important than quantity.', '106791201', '106791201-Bear-Crawl-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up in the starting position for Bear Crawl. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Cardio', 50, 7, 8, TRUE, TRUE, 'bear_crawl', 'Bear Crawl', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('03d8be0a-efd5-4d8a-9fa1-bfe2d2bed4b7', 'Standing Shoulder Mobilization In External R (Stick)', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Full body exercises are time-efficient and build functional, real-world strength.', '91811201', '91811201-Stick-Standing-Shoulder-Mobilization-In-External-R.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Stick Standing Shoulder Mobilization In External R. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'mobility', 'Stick Standing Shoulder Mobilization In External R', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('03e384eb-ece2-4bd8-bc0f-31674b5fd39c', 'Seated Neutral Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. Secondary activation of your forearms provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '3971201', '03971201-Dumbbell-Seated-Neutral-Wrist-Curl_Forearms.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Neutral Wrist Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'wrist_curl', 'Seated Neutral Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('03fec113-f60f-47e9-a8fa-8549528b243f', 'Bent Over Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Bending over allows gravity to provide resistance in a different plane. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '76251201', '76251201-Dumbbell-Bent-Over-Curl-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Over Curl. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Bent Over Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('0401333a-d8be-498e-8a08-8156d1aa65f2', 'Pull Up - Negative (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Pull Up (negative) is a pulling exercise that targets your latissimus dorsi for a wider back. You''ll also feel your biceps, upper back working to support the movement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '47741201', '47741201-Pull-up-(negative)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Focus on a slow, controlled lowering phase (3-5 seconds). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('040b77e8-5a4e-4b0d-a5c5-25b7b2e0d612', 'Single Arm Shoulder Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The triceps assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '3601201', '03601201-Dumbbell-One-Arm-Shoulder-Press-(VERSION-2)_Should.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'shoulder_press', 'Single Arm Shoulder Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('0420a53f-aa1f-468c-9877-4c5610f19b9d', 'Elbow To Knee Side Plank Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Works well as both a primary exercise or accessory movement.', '39361201', '39361201-Elbow-to-Knee-Side-Plank-Crunch-(female)_Wiast.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Keep tension on the target muscles throughout. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Elbow To Knee Side Plank Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('0423aac9-7451-4a64-8179-ce0887e67476', 'Elbow To Knee Side Plank Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger core with the Elbow To Knee Side Plank Crunch, focusing on your abs. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '35031201', '35031201-Elbow-to-Knee-Side-Plank-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Elbow To Knee Side Plank Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('042c7364-fc38-4fef-9564-7767484e7413', 'Double Side Step Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. The quads assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning. This variation is excellent for building mind-muscle connection.', '92531201', '92531201-Double-Side-Step-Walk-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Double Side Step Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Double Side Step Walk', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('043ae92a-c422-4118-9290-cecbcfcc739a', 'Side Bridge With Bent Leg (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '44571201', '44571201-Dumbbell-Side-Bridge-with-Bent-Leg-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Bridge With Bent Leg. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'glute_bridge', 'Side Bridge With Bent Leg', 'hip_thrust, romanian_deadlift', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('04440094-78b1-4d7d-898b-6880070af170', 'Lateral Step Up (Kettlebell)', 'Legs', 'Kettlebell, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this stepping exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. Lower body strength improves everything from walking to heavy compound lifts.', '80071201', '80071201-Kettlebell-Lateral-Step-Up-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Select an appropriately weighted kettlebell for Kettlebell Lateral Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'step_up', 'Lateral Step Up', 'lunge, split_squat, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('044c18b5-37e6-4618-9734-bde9f5bd81f5', 'Seated Military Press (Resistance Band, Chair)', 'Shoulders', 'Resistance Band, Chair', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Your triceps work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '91291201', '91291201-Resistance-Band-Sitting-Military-Press-on-a-Chair-.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Seated Military Press On A Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Start with the weight at shoulder level. 5. Press directly overhead until your arms are fully extended. 6. Lower back to shoulder level with control. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Military Press On A Chair', 'lateral_raise, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('0452729b-90db-4001-be1f-55e3edddfb44', 'Single Arm Clean And Push Press (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Shoulders","Quads","Hamstrings"}'::text[], 'Build total body strength and coordination with this multi-joint pressing movement. The shoulders, legs assist throughout the movement, making this a well-rounded exercise. Kettlebells are excellent for building functional, real-world strength. Compound movements like this develop coordination, power, and overall fitness.', '83191201', '83191201-Kettlebell-Single-arm-Clean-and-Push-Press-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Select an appropriately weighted kettlebell for Kettlebell Single Arm Clean And Push Press. 2. Execute the pressing motion for Kettlebell Single Arm Clean And Push Press, extending through the target muscles. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'clean', 'Single Arm Clean And Push Press', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('04626df8-9af4-450e-86c2-b51659616264', 'Bear Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Bear Plank is an explosive exercise that combines cardiovascular training with dynamic stabilization movements. Secondary activation of your shoulders, lower back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '41701201', '41701201-Bear-Plank_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Bear Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('0465f60f-8f19-4512-bac7-078fa24d3163', 'Lying Bench Crunch With Leg Adduction', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Bench Crunch With Leg Adduction, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Building core stability helps with everything from heavy deadlifts to daily activities.', '98831201', '98831201-Lying-Bench-Crunch-with-Leg-Adduction-(female)_Wai.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Bench Crunch With Leg Adduction. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'hip_adduction', 'Lying Bench Crunch With Leg Adduction', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('04684dcd-455d-4a9e-8e30-e64da6c228a3', 'High Knee Twist', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'Elevate your training with this twisting exercise that develops speed, power, and coordination. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '63831201', '63831201-High-Knee-Twist-(VERSION-2)-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Rotate your torso through the movement pattern for High Knee Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Twist', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('046977a3-1cbf-4fa1-9284-a626af05c6fa', 'Celebratory Knee Drives', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '59561201', '59561201-Celebratory-Knee-Drives-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Set up in the starting position for Celebratory Knee Drives. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Celebratory Knee Drives', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('046f787f-c468-4bfd-8b8f-8ff02460b9d2', 'Bear Crawl Push Up (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Dumbbell Bear Crawl Push Up is a pushing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '74801201', '74801201-Dumbbell-Bear-Crawl-Push-up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bear Crawl Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'bear_crawl', 'Bear Crawl Push Up', 'bench_press, chest_fly, dip, tricep_pushdown', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('047a320d-46e5-40f2-8837-ca0910b170d1', 'Twist (Band)', 'Core', 'Resistance Band', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. You''ll also feel your abs working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Building core stability helps with everything from heavy deadlifts to daily activities.', '9331201', '09331201-Band-twist_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Secure the resistance band appropriately for Band Twist. 2. Rotate your torso through the movement pattern for Band Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('047cbfea-e638-46fb-9294-c92eaa474275', 'Chest Bench Press Butt (Flat Bench)', 'Chest', 'Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Chest Bench Press Butt, an effective pressing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '23381201', '23381201-Chest-Bench-Press---Butt-(WRONG-RIGHT)_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'bench_press', 'Chest Bench Press Butt', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('048f37f5-e35e-4a96-8c7e-673fd8bbd22f', 'Standing Ballerina Side Knee Drive - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. You''ll also feel your hip flexors working to support the movement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '78461201', '78461201-Standing-Ballerina-Alternate-Side-Knee-Drive-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Alternate between sides/arms/legs with each repetition. 3. Complete all reps with control before resting. Don''t rush—quality over quantity. Include this in your plyometrics training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'knee_drive', 'Standing Ballerina Side Knee Drive - Alternating', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('04b53c4e-fbfa-46f5-8990-60738aa42fc9', '90 To 90 Leg Lift And Kickout', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Designed to lengthen your full body, the 90 To 90 Leg Lift And Kickout helps improve mobility and prevent stiffness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82661201', '82661201-90-to-90-Leg-Lift-and-Kickout-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Move into the stretch position for 90 To 90 Leg Lift And Kickout. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', '90 To 90 Leg Lift And Kickout', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('04bb6244-b9ac-4752-81de-fa6941cbac56', 'Decline Chest Press - Lying (Plate Machine)', 'Chest', 'Machine', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Lever Lying Decline Chest Press (plate Loaded), an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Performing this lying down removes momentum for stricter form. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics.', '88461201', '88461201-Lever-Lying-Decline-Chest-Press-(plate-loaded)_Che.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lying Decline Chest Press. 2. Lie down in the appropriate position for Lever Lying Decline Chest Press. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', 'Decline Press', 'Push', 'Compound', 'Bilateral', NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'decline_press', 'Lever Lying Decline Chest Press', 'bench_press, incline_bench_press, chest_fly, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('04bfadd5-7c8b-479c-b218-c14465125630', 'Suspended Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '8081201', '08081201-Suspended-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspended Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('04d72999-ed54-4440-bc7d-2551db06ce15', 'Triceps Extension (Cable) - Alternating', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '1491201', '01491201-Cable-Alternate-Triceps-Extension_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Adjust the cable machine to the correct height and attachment for Cable Alternate Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'tricep_extension', 'Triceps Extension - Alternating', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('04dd32be-4870-4964-b0d5-74bd5c2c9b35', 'Dynamic Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Use this stretch to open up your back area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension.', '4401201', '04401201-Dynamic-Back-Stretch-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Dynamic Back Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Dynamic Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('04ed302f-116c-4ae4-8f48-d55f92d192f1', 'Seated Military Press - Inside Squat Cage (Barbell)', 'Legs', 'Barbell, Flat Bench', '{"Quads","Glutes"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. You''ll also feel your triceps working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Barbells enable bilateral loading for building raw strength. Strong shoulders improve overhead strength and support nearly all upper body movements.', '10451201', '10451201-Barbell-Seated-Military-Press-(inside-squat-cage)_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Seated Military Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 81, 7, 9, TRUE, FALSE, 'shoulder_press', 'Seated Military Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('05026c84-f69f-4ce4-9408-42d2f146cd87', 'Mini Squat Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this squatting exercise that develops speed, power, and coordination. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '73381201', '73381201-Mini-Squat-Hop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat', 'Mini Squat Hop', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('050a2e4f-6a67-4458-8d58-b8848f15c19f', 'Knee Raise Step Jack', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. Your hip flexors work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '58061201', '58061201-Knee-Raise-Step-Jack-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in the prescribed direction for Knee Raise Step Jack. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Knee Raise Step Jack', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('0514a9f4-97a6-45c1-8b8d-d3dd96819e67', 'Weighted Straight Leg Diagonal Kickback (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '88021201', '88021201-Weighted-Dumbbell-Straight-Leg-Diagonal-Kickback-(.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Select a pair of dumbbells at an appropriate weight for Weighted Dumbbell Straight Leg Diagonal Kickback (. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Weighted  Straight Leg Diagonal Kickback (', 'Weighted Straight Leg Diagonal Kickback (', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('052737ab-e7f1-4374-9de2-a2e1495a03bc', 'Reverse Wrist Curl (Barbell)', 'Arms', 'Barbell', '{"Forearms"}'::text[], '{}'::text[], 'The Barbell Reverse Wrist Curl strengthens your forearms and grip through a curling motion. You''ll also feel your forearms working to support the movement. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '821201', '00821201-Barbell-Reverse-Wrist-Curl_Forearm.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Grip a barbell with hands at the appropriate width for Barbell Reverse Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, 'Overhand (Pronated)', 'Standard', 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'wrist_curl', 'Reverse Wrist Curl', 'hammer_curl, wrist_curl, bicep_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('0532891d-d139-4e4d-a013-820ae08b21d7', 'Seated Knee To Nose Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Seated Knee To Nose Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '73111201', '73111201-Seated-Knee-to-Nose-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Knee To Nose Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'knee_stretch', 'Seated Knee To Nose Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('05392c85-3bb5-4d9f-a96f-10d9b9535ed4', 'Archer Stepback', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Archer Stepback builds reactive power and improves conditioning. Secondary activation of your quads provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '55511201', '55511201-Archer-Stepback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Archer Stepback. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Archer Stepback', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('053af42b-8b77-4875-a06d-37c064289cbd', 'Punching - Alternating', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. Secondary activation of your shoulders provides additional muscle engagement. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '38021201', '38021201-Alternate-Punching-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Punching. 3. Execute the movement with proper form, focusing on your cardio. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Punching - Alternating', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('054e3f15-5aa8-4983-a65e-0543915c0ab6', 'Roll Hamstrings And Glute Seated On Floor (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Roll Hamstrings And Glute Seated On Floor is a hip-dominant movement exercise that targets your glutes. Being seated provides stability, allowing you to focus on the working muscles. Lower body strength improves everything from walking to heavy compound lifts.', '54301201', '54301201-Roll-Hamstrings-and-Glute-Sitting-on-Floor-(female.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Hamstrings And Glute Seated On Floor. 2. Sit on the floor with your legs positioned as required. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'glute_exercise', 'Roll Hamstrings And Glute Seated On Floor', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('0556a34f-86f3-418d-a010-39f50be7a8a1', 'Burpee (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. You''ll also feel your chest, quads working to support the movement. Using dumbbells requires more stabilization than barbell variations. Regular cardio training builds the aerobic base for better overall fitness.', '70891201', '70891201-Dumbbell-Burpee-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Burpee. 2. Squat down and place hands on the floor, jump feet back to plank. 3. Jump feet back toward hands, then explosively jump up with arms overhead. 4. Land softly and immediately begin the next rep. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 62, 9, 8, TRUE, TRUE, 'burpee', 'Burpee', 'mountain_climber, box_jump, jumping_jack', FALSE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('0558baa5-c52c-49ea-8055-cc794e38bac9', 'Lateral Box Jump (Plyo Box)', 'Legs', 'Plyo Box', '{"Quads"}'::text[], '{"Glutes","Hamstrings","Calves"}'::text[], 'A challenging plyometric exercise, the Lateral Box Jump builds reactive power and improves conditioning. The quads, calves assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '5641201', '05641201-Lateral-Box-Jump-(female)_Plyometrics-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Lateral Box Jump. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'box_jump', 'Lateral Box Jump', 'squat, burpee, broad_jump', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('056b76c8-0b57-41cd-a52f-0dd678c795ba', 'Lying Leg Lift Side', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Leg Lift Side is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '28521201', '28521201-Lying-Leg-Lift-Side-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie on your side with your body aligned. 2. Move into the stretch position for Lying Leg Lift Side. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Leg Lift Side', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0578dba5-78a0-4761-9a60-c273777f4f05', 'Lying Supine Abdominal Breathing', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '99771201', '99771201-Lying-Supine-Abdominal-Breathing-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie on your back with your body relaxed but ready. 2. Set up in the starting position for Lying Supine Abdominal Breathing. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'breathing', 'Lying Supine Abdominal Breathing', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('057ba54e-ee30-4a76-9d9f-f06312e8a8c9', 'Sissy Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes"}'::text[], 'The Sissy Squat Bodyweight is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '57291201', '57291201-Sissy-Squat-Bodyweight-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set. Works well for quads activation.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Sissy Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('058e5185-7ed8-4af0-9974-4a887469f50e', 'Front Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Suspender Front Plank is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. A strong core improves posture, protects your spine, and enhances all other lifts.', '72751201', '72751201-Suspender-Front-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Front Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'plank', 'Suspender Front Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('058f5e10-96a2-4bb7-b0d7-4f86a07bcf66', 'Wide Seated Good Morning', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. You''ll also feel your glutes, lower back working to support the movement. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84841201', '84841201-Wide-Seated-Good-Morning-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Wide Seated Good Morning. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_extension', 'Wide Seated Good Morning', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0593a6c7-f9f9-4e66-a9dc-6af493529902', 'Split Squat (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness. Focus on controlled form throughout each repetition.', '82851201', '82851201-Split-Squat-on-a-Chair-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'split_squat', 'Split Squat On A Chair', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0598f881-41e2-4b84-9336-548ea36652c6', 'Clasp Hands Shoulder Forward Roll', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This stretch specifically works on your shoulders, promoting flexibility and reducing muscle tightness. Your upper back work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension. Progress gradually by increasing resistance over time.', '96811201', '96811201-Clasp-Hands-Shoulder-Forward-Roll-(male)_Stretchin.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Move into the stretch position for Clasp Hands Shoulder Forward Roll. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Clasp Hands Shoulder Forward Roll', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('059d8193-cacb-48db-9fa1-05f3eb71f33a', 'Leg Extension - Single Leg (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{}'::text[], 'The Lever One Leg Extension is a extension exercise that primarily loads your quadriceps. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '57261201', '57261201-Lever-One-Leg-Extension-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever One Leg Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 83, 5, 7, FALSE, TRUE, 'leg_extension', 'Lever Single Leg Extension', 'squat, leg_press, lunge', TRUE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('05a98a03-ce91-4576-987b-3190271a3162', 'Leg Extension Star Crunch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{}'::text[], 'Strengthen your midsection with this extension movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '71441201', '71441201-Leg-Extension-Star-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Extend your legs until straight, squeezing your quads at the top. 2. Lower with control back to the starting position. 3. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_extension', 'Leg Extension Star Crunch', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('05ab1c73-18c8-48a9-8431-fb81a00a4938', 'Standing Behind Sky Reach', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '63251201', '63251201-Standing-Behind-Sky-Reach-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Behind Sky Reach. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_stretch', 'Standing Behind Sky Reach', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('05b8d5ad-eb7d-401b-8bd8-cd866d53a89b', 'Single Arm Deadlift (Dumbbell)', 'Back', 'Dumbbells', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '69501201', '69501201-Dumbbell-Single-Arm-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'deadlift', 'Single Arm Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('05b9aa62-2890-4c39-b8b7-f00d07080f31', 'Alternative Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your front delts provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '93071201', '93071201-Cable-Alternative-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Adjust the cable machine to the correct height and attachment for Cable Alternative Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Alternative Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('05c70cf0-3202-44d4-8706-4c04b89d92e5', 'Kneeling Hip Thrust', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '46691201', '46691201-Kneeling-Hip-Thrust-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Kneeling Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('05c8d293-e5fc-4650-aa97-9eb23a8ff5f2', 'Upright Row (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. You''ll also feel your traps working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Shoulder development enhances both performance and upper body aesthetics.', '70221201', '70221201-Kettlebell-Upright-Row-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Select an appropriately weighted kettlebell for Kettlebell Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'upright_row', 'Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('05cc9846-bc12-411a-886f-2c16dcb507bd', 'Hamstring Curl Overhead Clap (Gymnastic Rings) - Alternating', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Build power and athleticism with this high-intensity curling exercise that challenges your entire body. The forearms assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '82881201', '82881201-Alternating-Hamstring-Curl-Overhead-Clap-(male)_Pl.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'leg_curl', 'Hamstring Curl Overhead Clap - Alternating', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 60, 2, 68, 85, 85, 70),
('05fdc551-ea3d-4987-8a44-b5b74cdbbdb0', 'Standing Pec Dec', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'The Bodyweight Standing Pec Dec is a movement exercise that targets your chest muscles. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '94221201', '94221201-Bodyweight-Standing-Pec-Dec-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Bodyweight Standing Pec Dec. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_exercise', 'Standing Pec Dec', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('062b8b79-ca44-4d8d-8511-4e93157ba50c', 'Gate Rock', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. This variation is excellent for building mind-muscle connection.', '87751201', '87751201-Gate-Rock-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Move into the stretch position for Gate Rock. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Gate Rock', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('063a968e-8c47-4b1a-8e83-4eac11ffcba9', 'Kneeling Thoracic Spine Extension', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Thoracic Spine Extension is a lower body extension exercise that targets your core. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '98851201', '98851201-Kneeling-Thoracic-Spine-Extension-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Extend through the target joint(s) for Kneeling Thoracic Spine Extension. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'spinal_stretch', 'Kneeling Thoracic Spine Extension', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('064eb8e2-32b9-4256-858c-2ac5bfa44c78', 'Lying Vertical Hamstring Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Use this stretch to open up your hamstrings area and enhance overall flexibility. Your lower back work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '82081201', '82081201-Lying-Vertical-Hamstring-Stretch-(female)_Stretchi.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Vertical Hamstring Stretch. 2. Move into the stretch position for Lying Vertical Hamstring Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 28, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Lying Vertical Hamstring Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('065c1b70-8ae6-4450-8064-2046e4cca407', 'Skull Crusher (EZ Bar)', 'Arms', 'EZ Bar, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This movement movement isolates your triceps for improved arm development. Dedicated arm training builds both strength and muscular definition.', '103811201', '103811201-EZ-Bar-Skull-Crusher-(VERSION-2)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Set up in the starting position for EZ Bar Skull Crusher. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'tricep_extension', 'EZ Bar Skull Crusher', 'tricep_pushdown, close_grip_bench', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('065ce37d-4df8-4770-b960-7ddb3c603011', 'Bench Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness. Perfect for including in both strength and hypertrophy programs.', '261201', '00261201-Barbell-Bench-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('065f83ef-7290-473f-ac33-8ed4994ceabd', 'Kneeling Single Arm Horizontal Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps, rear delts provides additional muscle engagement. The kneeling position adds a core stability challenge. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '106671201', '106671201-Cable-Kneeling-Single-Arm-Horizontal-Row-(male)_B.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Single Arm Horizontal Row. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'arm_exercise', 'Kneeling Single Arm Horizontal Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('0661c1aa-6a2a-4034-80a3-84cb8b5beeb1', 'Hamstring Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Hamstring Bridge targets your hamstrings through a controlled bridging motion. Secondary activation of your hamstrings provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '101801201', '101801201-Hamstring-Bridge-(VERSION-2)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'glute_bridge', 'Hamstring Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 68, 85, 85, 70),
('066bffb2-cd0a-41a8-9d1b-78319da22b3e', 'Incline Single Arm Lat Pulldown (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. You''ll also feel your biceps, upper back working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '79341201', '79341201-Cable-Incline-Single-Arm-Lat-Pulldown-(female)_Bac.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Single Arm Lat Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Incline Single Arm Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('067277f3-0884-48ce-992e-3871c20d46ae', 'Adductors Stretch Coronal Plane', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'Build leg strength with this stretching movement focusing on your adductors. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength. Control the negative portion for maximum muscle engagement.', '76911201', '76911201-Adductors-Stretch-Coronal-Plane-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Set up in the starting position for Adductors Stretch Coronal Plane. 2. Execute the movement with proper form, focusing on your adductors. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_adduction', 'Adductors Stretch Coronal Plane', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('06736e71-94da-43d5-b8fb-a0c114292148', 'Backkick Triceps Extension', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Backkick Triceps Extension is an explosive exercise that combines cardiovascular training with dynamic extension movements. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '84621201', '84621201-Backkick-Triceps-Extension-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'Backkick Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('067adab3-c043-42ce-a4fa-6b6c9a52aed4', 'Low Lunge Yoga Pose Anjaneyasana I', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '66181201', '66181201-Low-Lunge-Yoga-Pose-Anjaneyasana-I-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'lunge', 'Low Lunge Yoga Pose Anjaneyasana I', 'split_squat, step_up, squat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('067cf622-b965-430f-9949-d1bc69bcca46', 'Side Bend (TRX)', 'Core', 'TRX', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Suspender Side Bend, focusing on your abs. The abs assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. A strong core improves posture, protects your spine, and enhances all other lifts.', '10971201', '10971201-Suspender-Side-Bend-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Side Bend. 2. Set up in the starting position for Suspender Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'side_bend', 'Suspender Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('067ed029-a69f-4c12-883b-aeb5aaaf5514', 'Renegade Row (Kettlebell) - Alternating', 'Back', 'Kettlebell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Kettlebell Alternating Renegade Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. A strong back improves posture, prevents injury, and balances pressing movements.', '5211201', '05211201-Kettlebell-Alternating-Renegade-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select an appropriately weighted kettlebell for Kettlebell Alternating Renegade Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Alternate between sides/arms/legs with each repetition. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Renegade Row - Alternating', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('0695f70d-828b-415e-a2b4-ecb8df3f50eb', 'Single Arm Lateral Raise', 'Shoulders', 'Bodyweight', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '93051201', '93051201-Bodyweight-Single-Arm-Lateral-Raise-(male)_Shoulde.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'lateral_raise', 'Single Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('069fe6fb-93f9-4c10-b296-563d0f467cdb', 'Lying Ab Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '77331201', '77331201-Lying-Ab-Hold-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Ab Hold. 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'core_exercise', 'Lying Ab Hold', 'plank, crunch, leg_raise', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('06ac78e2-5253-428b-826b-d241e8956efc', 'Pull Up - Reverse Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function. Can be modified for beginners or progressed for advanced athletes.', '38951201', '38951201-Reverse-grip-Pull-up-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Use a reverse grip (opposite of the standard grip for this exercise). 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Pull Up - Reverse Grip', 'Pull Up - Reverse Grip', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('06acbe2b-4562-41ef-a08c-bc735c36125a', 'Lying Full Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Full Leg Raise is a lower body raising exercise that targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '32631201', '32631201-Lying-Full-Leg-raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Full Leg Raise. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Full Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('06ad1667-8fcd-47f0-aa59-4b4cc3cbb4cb', 'Front Raise Skater Stepback', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Front Raise Skater Stepback is an explosive exercise that combines cardiovascular training with dynamic raising movements. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '89121201', '89121201-Front-Raise-Skater-Stepback-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'front_raise', 'Front Raise Skater Stepback', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('06b9c967-f602-488f-bd38-14594b07cff8', 'Incline Y Raise (Band)', 'Shoulders', 'Resistance Band, Incline Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build stronger shoulders with this raising movement focusing on your delts. Secondary activation of your upper back provides additional muscle engagement. The incline angle shifts emphasis toward the upper portion of the target muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '68651201', '68651201-Band-Incline-Y-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Secure the resistance band appropriately for Band Incline Y Raise. 2. Raise the weight in the prescribed direction for Band Incline Y Raise. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline Y Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('06c3981b-a263-409e-b018-2efe16124f72', 'Hip Thrust (Smith Machine)', 'Legs', 'Smith Machine', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'The Smith Hip Thrust is a hip-dominant thrusting exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '31101201', '31101201-Smith-Hip-Thrust_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'hip_thrust', 'Smith Hip Thrust', 'Hip Thrust', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('06c7fde4-a0e5-4cea-89a1-4e7d4451ed4f', 'Bicep Curl (Kettlebell)', 'Arms', 'Kettlebell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Kettlebells are excellent for building functional, real-world strength. Dedicated arm training builds both strength and muscular definition.', '69331201', '69331201-Kettlebell-Biceps-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'bicep_curl', 'Bicep Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('06d8ac0c-85c7-4914-9def-671625d7a2cc', 'Rope Climb', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Biceps","Forearms"}'::text[], 'This climbing exercise emphasizes your lats for improved back development. You''ll also feel your biceps, grip working to support the movement. Back development is crucial for pulling strength and overall upper body function.', '6801201', '06801201-Rope-Climb_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Set up in the starting position for Rope Climb. 2. Execute the movement with proper form, focusing on your lats. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'rope_climb', 'Rope Climb', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('06e3b24d-95bb-451a-8718-fba65a750a8f', 'Serratus Wall Slide (Stability Ball)', 'Shoulders', 'Stability Ball, Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Exercise Ball Serratus Wall Slide is a movement exercise that develops back strength and muscle. You''ll also feel your upper back working to support the movement. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '53111201', '53111201-Exercise-Ball-Serratus-Wall-Slide_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Position the stability ball as needed for Exercise Ball Serratus Wall Slide. 2. Position yourself at the appropriate distance from a wall. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 34, 7, 8, TRUE, TRUE, 'serratus', 'Exercise Ball Serratus Wall Slide', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('06f4ce10-7e5c-4ff0-9e6e-7a4bb9a1cff6', 'Hammer Grip Pull Up On Dip Cage (Pull-Up Bar)', 'Back', 'Pull-Up Bar, Dip Bars', '{"Lats","Upper Back"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Your biceps, upper back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '38981201', '38981201-Hammer-Grip-Pull-up-on-Dip-Cage-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Use a hammer/neutral grip with palms facing each other throughout. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Hammer Grip Pull Up On Dip Cage', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('06f9b5b8-eddd-455f-b40f-7af2ecf28ca0', 'Kickback (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. You''ll also feel your hamstrings working to support the movement. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '8601201', '08601201-Cable-kickback_Upper-arms_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Kickback', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('070b353a-42fd-4e41-81df-6337942184ad', 'Pull Through (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pulling exercise isolates your glutes for improved hip strength and power. Your hamstrings work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '57351201', '57351201-Cable-Pull-Through-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Pull Through. 2. Set up in the starting position for Cable Pull Through. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'pull_through', 'Pull Through', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('0714bc1f-1f67-420c-90a4-49f44bd70bb2', 'Push Up (Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Band Push Up, an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '9151201', '09151201-Band-Push-up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('072ca7ee-7b2b-4bcd-91b1-29e8a8af9015', 'Diagonal Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity lunging exercise that challenges your entire body. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '46371201', '46371201-Diagonal-Lunge-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Diagonal Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('07315796-424f-416a-9d79-724a0bc08843', 'Glute Dominant Bulgarian Split Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbell Glute Dominant Bulgarian Split Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '75901201', '75901201-Dumbell-Glute-Dominant-Bulgarian-Split-Squat-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbell Glute Dominant Bulgarian Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'split_squat', 'Dumbell Glute Dominant Bulgarian Split Squat', 'split_squat, lunge, leg_press', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('07377926-0d6b-43aa-99c8-7df4fc0c4916', 'Hip External Rotator Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'The Hip External Rotator Stretch provides a deep stretch for your hips, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '19441201', '19441201-Hip-External-Rotator-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Move into the stretch position for Hip External Rotator Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'external_rotation', 'Hip External Rotator Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('07429137-17cf-4af3-8817-83331f0d131b', 'Twisting Pull (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Cable Twisting Pull is a pulling exercise that develops back strength and muscle. The abs assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '2441201', '02441201-Cable-Twisting-Pull_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Adjust the cable machine to the correct height and attachment for Cable Twisting Pull. 2. Rotate your torso through the movement pattern for Cable Twisting Pull. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Twisting Pull', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('0746a5ad-2a4b-4edc-8e28-766430e845bf', 'Chest Press - Narrow Grip (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Lever Parallel Chest Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '10291201', '10291201-Lever-Parallel-Chest-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Parallel Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Parallel Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('076f7b14-5c66-4d23-a7c4-a8246a24248e', 'Kneeling Sartorius Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Kneeling Sartorius Stretch provides a deep stretch for your full body, ideal for recovery and mobility work. Kneeling helps eliminate lower body momentum from the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '67701201', '67701201-Kneeling-Sartorius-Stretch-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Sartorius Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Kneeling Sartorius Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('07806ecf-aa72-485e-b23f-ddcb0baa384c', 'Knee Leg Lifts', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Knee Leg Lifts is an explosive exercise that combines cardiovascular training with dynamic movement movements. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '62051201', '62051201-Knee-Leg-Lifts-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Set up in the starting position for Knee Leg Lifts. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Knee Leg Lifts', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('078368eb-ff3b-4129-9ade-1b483195f3d4', 'Bench Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbbell Bench Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '22171201', '22171201-Dumbbell-Bench-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bench Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('078c0c63-480b-4680-9fa5-36b9a38ba57c', 'Lying Legs Extension Toes Flexion', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Legs Extension Toes Flexion is a lower body extension exercise that targets your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '96571201', '96571201-Lying-Legs-Extension-Toes-Flexion-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Lie down in the appropriate position for Lying Legs Extension Toes Flexion. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_exercise', 'Lying Legs Extension Toes Flexion', 'leg_curl, squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('078e1668-d0ab-4e84-9bae-615918143cd0', 'Staggered Stance Deadlift (Kettlebell)', 'Back', 'Kettlebell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The kettlebell grip position adds a unique training stimulus. Lower body strength improves everything from walking to heavy compound lifts.', '88921201', '88921201-Kettlebell-Staggered-Stance-Deadlift-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Staggered Stance Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'deadlift', 'Staggered Stance Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('07940854-0ca9-4c85-acdd-49395fed85a5', 'Romanian Deadlift To Row (Barbell)', 'Legs', 'Barbell', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this rowing movement focusing on your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '74821201', '74821201-Barbell-Romanian-Deadlift-to-Row-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Grip a barbell with hands at the appropriate width for Barbell Romanian Deadlift To Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Romanian Deadlift To Row', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('07a015d1-af7a-4ab9-b268-bb4df2744733', 'Hip Thrust (Plate Loaded)', 'Legs', 'Machine', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Lower body strength improves everything from walking to heavy compound lifts.', '73841201', '73841201-Lever-Hip-Thrust-(plate-loaded)-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'hip_thrust', 'Lever Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('07a91a7e-9a27-4cd7-916b-9cc8838299a6', 'Child To Cobra Pose', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Target your abs with this movement stretch that helps restore range of motion. The lower back assist throughout the movement, making this a well-rounded exercise. Flexibility work like this enhances performance and prevents stiffness.', '79521201', '79521201-Child-to-Cobra-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Child To Cobra Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Child To Cobra Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('07bbcfa8-91e6-4457-925d-405bb608f8fe', 'Deadlift (Kettlebell)', 'Back', 'Kettlebell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. Strong legs are the foundation for athletic performance and functional fitness.', '39021201', '39021201-Kettlebell-deadlift-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'deadlift', 'Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('07bd6001-34a0-4ba2-9991-1e4dba41a097', 'Lying On Floor Hammer Press (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The lying position provides back support and helps isolate the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. A well-developed chest contributes to upper body strength and aesthetics.', '34251201', '34251201-Dumbbell-Lying-on-Floor-Hammer-Press-(female)_Ches.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying On Floor Hammer Press. 2. Position yourself on the floor for Dumbbell Lying On Floor Hammer Press. 3. Lie down in the appropriate position for Dumbbell Lying On Floor Hammer Press. 4. Use a hammer/neutral grip with palms facing each other throughout. 5. Lower the weight toward your chest with control. 6. Press the weight up until your arms are extended (don''t lock elbows). 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'squeeze_press', 'Lying On Floor Hammer Press', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('07c06504-cd56-45cc-8dc5-40c19ea749b0', 'Floor T Raise', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'This raising exercise works your rear delts for improved shoulder strength and aesthetics. Your upper back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '64921201', '64921201-Floor-T-Raise-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Position yourself on the floor for Floor T Raise. 2. Raise the weight in the prescribed direction for Floor T Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'lateral_raise', 'Floor T Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('07c7b6ac-b503-45db-b422-98e60764a83e', 'Sit Up Stand Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '64331201', '64331201-Sit-up-Stand-up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Set up in the starting position for Sit Up Stand Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Sit Up Stand Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('07d4934c-5f50-41c6-b496-2efa02aa1c72', 'Hip Adduction (Cable)', 'Legs', 'Cables', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Cable Hip Adduction is a lower body movement exercise that targets your adductors. Cable resistance creates smooth, continuous muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '1681201', '01681201-Cable-Hip-Adduction_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Adjust the cable machine to the correct height and attachment for Cable Hip Adduction. 2. Set up in the starting position for Cable Hip Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'hip_adduction', 'Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('07d74f89-e482-4c13-9d36-176f6f98276a', 'Seated Squeeze Shoulder Blades Chest Stretch On A', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Seated Squeeze Shoulder Blades Chest Stretch On A provides a deep stretch for your shoulders, ideal for recovery and mobility work. You''ll also feel your upper back working to support the movement. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '104631201', '104631201-Seated-Squeeze-Shoulder-Blades-Chest-Stretch-on-a.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Squeeze Shoulder Blades Chest Stretch On A. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'chest_stretch', 'Seated Squeeze Shoulder Blades Chest Stretch On A', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('07e79879-c7ed-4242-8ec2-9d181c517690', 'Seated Shoulders Circle - Alternating', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. The seated position helps isolate the target muscles by removing momentum. Strong shoulders improve overhead strength and support nearly all upper body movements.', '87321201', '87321201-Seated-Alternate-Shoulders-Circle-(female)_Shoulde.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulders Circle - Alternating', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('07eeddc9-4a40-4535-88a1-eec6b028c76b', 'By Major Groups Muscle Body', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Strengthen your midsection with this movement movement that works your full body. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '12521201', '12521201-By-MAJOR-GROUPS-Muscle-body-(female)_UNITED.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Set up in the starting position for By Major Groups Muscle Body _united. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'By Major Groups Muscle Body', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('08130863-ac09-4d17-b7ad-896fe0640708', 'Jab Cross Left Hook Uppercut (combo)', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Your shoulders, core work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '104421201', '104421201-Jab-Cross-Left-Hook-Uppercut-(combo)_Boxing_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up in the starting position for Jab Cross Left Hook Uppercut. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Jab Cross Left Hook Uppercut', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('0813cb68-e118-4810-90b4-49e6ce932dca', 'Lying Side Lift Free Lateral Flexion', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Target your core with this flexion stretch that helps restore range of motion. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '94051201', '94051201-Lying-Side-Lift-free-Lateral-Flexion-(female)_Stre.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie on your side with your body aligned. 2. Move into the stretch position for Lying Side Lift Free Lateral Flexion. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Lying Side Lift Free Lateral Flexion', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('081af7c7-5b40-4bd2-ab41-d7e5dae1d64e', 'Decline Hammer Press (Dumbbell)', 'Chest', 'Dumbbells, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Dumbbell Decline Hammer Press, an effective pressing movement for upper body strength. Declining shifts the emphasis to hit the muscles from a different angle. The dumbbell variation provides freedom of movement and greater range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '3031201', '03031201-Dumbbell-Decline-Hammer-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Hammer Press. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', 'Press', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'decline_press', 'Decline Hammer Press', 'bench_press, incline_bench_press, chest_fly, dip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('081e418a-f026-4661-8bf4-5d2d7c3c7edc', 'Roll Anterior Calf Foam Rolling (Foam Roller)', 'Legs', 'Foam Roller', '{"Calves"}'::text[], '{}'::text[], 'The Roll Anterior Calf Foam Rolling isolates your calf muscles through a movement motion. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '29471201', '29471201-Roll-Anterior-Calf-Foam-Rolling_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Set up in the starting position for Roll Anterior Calf Foam Rolling. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'foam_roll', 'Roll Anterior Calf Foam Rolling', 'stretch_general, mobility_drill', FALSE, 'foam_roller', TRUE, 1, 30, 2, 70, 88, 95, 65),
('0820bc13-4459-4f9e-8309-b8c14df4224a', 'Standing Elbow Clap', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '55001201', '55001201-Standing-Elbow-Clap-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Elbow Clap. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Elbow Clap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('08330208-33eb-419b-8d4b-c7e7d2c7e8b8', 'Front Squat With V Bar (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '75781201', '75781201-Cable-Front-Squat-with-V-bar_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Adjust the cable machine to the correct height and attachment for Cable Front Squat With V Bar. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 95, 7, 8, TRUE, TRUE, 'front_squat', 'Front Squat With V Bar', 'squat, leg_press, leg_extension, goblet_squat', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('083c4567-39f9-4b8c-be61-0a78e9abe6ff', 'Z Press (Dumbbell) - Alternating', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Dumbbell Alternate Z Press is a pressing exercise that targets your delts for shoulder development. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '68911201', '68911201-Dumbbell-Alternate-Z-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Alternate Z Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'Z Press - Alternating', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('084feee5-5a71-408a-9c83-ce356959a8a2', 'Bridge Pose Setu Bandhasana', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Bridge Pose Setu Bandhasana is a hip-dominant bridging exercise that targets your glutes. Secondary activation of your hamstrings provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '9411201', '09411201-Bridge-Pose-Setu-Bandhasana-(female).mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Secure the resistance band appropriately for Bridge Pose Setu Bandhasana. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Bridge Pose Setu Bandhasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 60, 85, 90, 50),
('085be7ee-0ba3-4a2b-b6e1-1b8d76992000', 'Kneeling Back Leg Lift Curl', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Kneeling Back Leg Lift Curl is a lower body curling exercise that targets your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '57981201', '57981201-Kneeling-Back-Leg-Lift-Curl-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Curl your heels toward your glutes by bending at the knees. 3. Squeeze your hamstrings at peak contraction. 4. Extend legs back out with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_exercise', 'Kneeling Back Leg Lift Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('086dbd6f-d8c6-4f5b-815e-7c3eef602286', 'Seated Chest Press (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Seated Chest Press On A Chair is a pressing exercise that targets your chest muscles. Your triceps, front delts work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '86181201', '86181201-Seated-Chest-Press-on-a-Chair-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'bench_press', 'Seated Chest Press On A Chair', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('087229d5-2ec7-462f-9217-4a040d722de6', 'Single Leg Split Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '22271201', '22271201-Barbell-Single-Leg-Split-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Single Leg Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', 'Squat', 'Push', 'Compound', 'Unilateral', NULL, 4, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'split_squat', 'Single Leg Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('0875d94b-a08b-42ed-9f04-b0bcf54c413e', 'Nordic Hamstring Curl (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This curling movement works your hamstrings for balanced leg development. Your forearms work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '77461201', '77461201-Nordic-Hamstring-Curl-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'leg_curl', 'Nordic Hamstring Curl', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 60, 2, 68, 85, 85, 70),
('0880f1af-032d-40dd-922f-3d36db4bd3b5', 'Hanging Front Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. The hip flexors, grip assist throughout the movement, making this a well-rounded exercise. Hanging adds a grip and core stability component to the exercise. Machine exercises are great for isolating muscles and training to failure safely. A strong core improves posture, protects your spine, and enhances all other lifts.', '72511201', '72511201-Hanging-Front-Lever-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Hanging Front Lever Raise. 2. Grip the bar and hang with arms fully extended, engaging your shoulders. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 5, 5, 7, FALSE, TRUE, 'front_lever', 'Hanging Front Lever Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 80, 75, 20, 88),
('08953058-adc7-4c22-93f3-33180e58358d', 'Push Up 3 Points Hops', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Push Up 3 Points Hops is an explosive exercise that combines cardiovascular training with dynamic pushing movements. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '75301201', '75301201-Push-up-3-Points-Hops-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep. Works well for chest activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Push Up 3 Points Hops', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('089ab9b0-f01b-42be-89e5-f340eccbc6dd', 'Good Morning (Kettlebell)', 'Back', 'Kettlebell', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'This movement movement works your hamstrings for balanced leg development. Secondary activation of your glutes, lower back provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Lower body strength improves everything from walking to heavy compound lifts.', '48171201', '48171201-Kettlebell-Good-Morning_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select an appropriately weighted kettlebell for Kettlebell Good Morning. 2. Set up in the starting position for Kettlebell Good Morning. 3. Execute the movement with proper form, focusing on your hamstrings. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'back_extension', 'Good Morning', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('089eb0fd-57ab-486b-b399-4c7acb206c08', 'Side Plank Hip Adduction', 'Legs', 'Bodyweight', '{"Core","Abs"}'::text[], '{}'::text[], 'Build leg strength with this stabilization movement focusing on your adductors. You''ll also feel your shoulders, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '57811201', '57811201-Side-Plank-Hip-Adduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form. This variation specifically emphasizes the adductors.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('08b4572e-d7e1-4114-b886-679b8a13064b', 'Lean Back Air Cycling (Chair)', 'Core', 'Stationary Bike, Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lean Back Air Cycling On A Chair is a core movement exercise that primarily targets your abs. Core strength is foundational for athletic performance and injury prevention.', '76681201', '76681201-Lean-Back-Air-Cycling-on-a-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Lean Back Air Cycling On A Chair. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 35, 9, 8, FALSE, TRUE, 'cycling', 'Lean Back Air Cycling On A Chair', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('08b9cd53-185f-4c55-b6ce-bc75075ecfc6', 'Back Extension (Stability Ball)', 'Back', 'Stability Ball', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build a stronger back with this extension movement targeting your lower back. Secondary activation of your glutes provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Back development is crucial for pulling strength and overall upper body function.', '13141201', '13141201-Back-Extension-on-Exercise-Ball_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Position the stability ball as needed for Back Extension On Exercise Ball. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'back_extension', 'Back Extension On Exercise Ball', 'good_morning, bird_dog, superman', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('08ca5785-8446-4238-82e2-329491990d2d', 'Side Walk Tip Toes', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Can be modified for beginners or progressed for advanced athletes.', '58081201', '58081201-Side-Walk-Tip-Toes-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Set up in the starting position for Side Walk Tip Toes. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'calf_raise', 'Side Walk Tip Toes', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('08d66e08-7fad-494e-a791-b27b94e51287', 'Walking Front Side Top Punch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. Secondary activation of your shoulders provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '99171201', '99171201-Walking-Front-Side-Top-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking Front Side Top Punch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking Front Side Top Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('08dc5acc-2634-4252-a1a1-6a8ee96b839a', 'Bicep Curl (Dumbbell) - Alternating', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '25841201', '25841201-Dumbbell-Alternate-Biceps-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Alternate Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', 'Curl', 'Pull', 'Compound', 'Unilateral', NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'bicep_curl', 'Bicep Curl - Alternating', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('08ee9121-238a-4d08-9511-9d523691e1dd', 'Hip Circles Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. Flexibility work like this enhances performance and prevents stiffness. Perfect for including in both strength and hypertrophy programs.', '42861201', '42861201-Hip-Circles-Stretch-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Move into the stretch position for Hip Circles Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_circle', 'Hip Circles Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
